  const barrel = lathe([[0.011, 0], [0.011, 0.16], [0.008, 0.17], [0.008, 0.30], [0.010, 0.31], [0.010, 0.33]], MAT.steelDark);
  barrel.rotation.x = Math.PI / 2; // lathe Y -> +Z
